data.transform:
{
  "raw": {
    "request": $state.context.request,
    "response": $
  },
  "errors": $isNilOrEmpty(Errors) ? undefined : [Errors.($omit($, ["request"]))],
  "error": $not($isNilOrEmpty(Errors)),
  "request": $state.context.parameters,
  "response": ShipmentResponse.ShipmentResults.{
    "trackingNumber": ShipmentIdentificationNumber,
    "charges": $coalesce([NegotiatedRateCharges, ShipmentCharges]).{
      /* For negotiated rates, the property is TotalCharge; for non-negotiated, it's TotalCharges. */
      "totalCharges": $coalesce([TotalCharge, TotalCharges]).{
        "value": $number(MonetaryValue),
        /* TODO: Look up unit based on CurrencyCode */
        "unitId": "usDollar"
      }
    },
    "packageLabels": [PackageResults.{
      "trackingNumber": TrackingNumber,
      "label": ShippingLabel.{
        "data": $base64decode(GraphicImage),
        "format": ImageFormat.Code
      }
    }]
  }
}

(
  $formatAddress := function($address) {
    {
      "AddressLine": $address.lines,
      "City": $address.city,
      "StateProvinceCode": $address.state,
      "PostalCode": $address.postalCode,
      "CountryCode": $address.country,
      "ResidentialAddressIndicator": $address.residential = true ? '' : undefined
    }
  };

  $formatPhone := function($phone) {
    $not($isNilOrEmpty($phone)) ? {
      /* Carrier expects just a bare number. */
      "Number": $phone
        ~> $split('')
        ~> $filter(?, function($v) { $match($v, /\d/) })
        ~> $join('')
    }
  };

  $getWeightUnit := function($unit) {(
    $unit := $uppercase($coalesce([$unit, 'LBS']));

    $unit = 'LB' or $unit = 'LBS'
        ? 'LBS'
      : $unit = 'KG' or $unit = 'KGS'
        ? 'KGS'
      : $unit
  )};

  $getReferenceType := function($type) {
    $type = 'serialNumber'
      ? 'SE'
      : $type = 'purchaseOrderNumber'
        ? 'PO'
        : 'TN'
  };

  $shipment := $state.context.parameters.shipment;
  $shipperAccount := $shipment.integratedCarrierConnectionConfiguration.shipperIntegratedCarrierAccount;

  $shipFrom := $coalesce([$shipment.shipFrom, $shipperAccount]);

  $shipTo := $shipment.shipTo;

  $billToAccount := $shipment.integratedCarrierBillToAccount;

  $service := $shipment.integratedCarrierService;

  $packages := $shipment.packageDefinitions;

  {
    "request": {
      "action": "POST",
      "path": "/ship/v1/shipments",
      "version": "v1", 
      "data": {    
        "ShipmentRequest": {
          "LabelSpecification": {
            "LabelImageFormat": {
              "Code": "ZPL" /* Valid options: EPL; SPL; ZPL; GIF; STARPL */
            },
            "LabelStockSize": {
              "Height": "6", /* Only valid values are 6 and 8; 8 would be used for labels with doctabs (?) */
              "Width": "4" /* Only valid value is 4 */
            }
          },
          "Shipment": {
            "Description": $shipment.description,
            "Shipper": $shipperAccount.{
              "Name": name,
              "Phone": $formatPhone(phoneNumber),
              "ShipperNumber": accountNumber,
              "Address": $formatAddress(address)
            },
            "ShipFrom": $shipFrom.{
              "Name": name,
              "Phone": $formatPhone(phoneNumber),
              "Address": $formatAddress(address)
            },
            "ShipTo": $shipTo.{
              "Name": name,
              "Phone": $formatPhone(phoneNumber),
              "Address": $formatAddress(address)
            },
            "PaymentInformation": {
              "ShipmentCharge": $billToAccount.{
                "Type": "01", /* "01" = Transportation, "02" is Duties and Taxes (only valid for international shipments) */
                integratedCarrierBillingType.code: {
                  "AccountNumber": accountNumber,
                  "Address": {
                    "PostalCode": address.postalCode,
                    "CountryCode": address.country
                  }
                }
              }
            },
            "Service": $service.{
              /* Code is required; Description is optional and not validated. */
              "Code": code,
              "Description": name
            },
            "ShipmentRatingOptions": {
              "NegotiatedRatesIndicator": ""
            },
            /*  Shipment-level refernce numbers are used for shipments OTHER than US/US or PR/PR.
                When we do international shipping, we'll pull the reference numbers off the first package.
            "ReferenceNumber": $shipment.referenceNumbers.{
              "BarCodeIndicator": barcode ? "",
              "Code": type,
              "Value": $string(value)
            }, 
            */
            "Package": [$packages.{
              "Description": description,
              "Packaging": {
                /* 02 is "customer supplied"; other options are USPS flat-rate boxes, pallets, etc. */
                "Code": "02"
              },
              "Dimensions": $isNilOrEmpty(dimensions) = false ? { 
                "UnitOfMeasurement": {
                  /* IN = Inches CM = Centimeters 00 = Metric Units 01 = English Units     */
                  "Code": dimensions.length.unit.code ? $uppercase(dimensions.length.unit.code) : "IN"
                },
                "Length": $string(dimensions.length.value),
                "Width": $string(dimensions.width.value),
                "Height": $string(dimensions.height.value)
              },
              "PackageWeight": {
                "UnitOfMeasurement": {
                  /* LBS = Pounds KG = Kilograms 00 = Metric Units 01 = English Units     */
                  "Code": $getWeightUnit(weight.unit.code)
                },
                "Weight": $string(weight.value)
              },
              /*  Package-level refernce numbers are used for shipments from/to US/US or PR/PR. */
              "ReferenceNumber": referenceNumbers#$i.{
                "BarCodeIndicator": $i = 0 ? "",
                /* Reference enum table */
                "Code": $getReferenceType(type),
                "Value": $string(value)
              }
            }]
          }
        }
      }
    }
  }
)

